import type { WixDataInsertOptions } from './types'

/**
 * Options builder for insert operations.
 *
 * Use this builder to configure insert behavior such as hooks suppression,
 * and reference handling.
 * @public
 * @builder
 * @documentationMaturity preview
 */
export interface WixDataInsertOptionsBuilder {
  /**
   * Sets whether to suppress insert hooks.
   *
   * When `true`, the insert runs without triggering hooks.
   */
  withSuppressHooks(value: boolean): WixDataInsertOptionsBuilder
  /**
   * Sets whether to include draft items when inserting an item.
   * @internal
   */
  withShowDrafts(value: boolean): WixDataInsertOptionsBuilder
  /**
   * Sets whether to include references when inserting an item.
   * @internal
   */
  withIncludeReferences(value: boolean): WixDataInsertOptionsBuilder
  /**
   * Sets whether to save referenced items when inserting an item.
   */
  withSaveReferences(value: boolean): WixDataInsertOptionsBuilder
  /**
   * Builds the insert options object.
   */
  build(): WixDataInsertOptions
}

class WixDataInsertOptionsBuilderImpl implements WixDataInsertOptionsBuilder {
  constructor(private readonly options: WixDataInsertOptions = {}) {}

  withSuppressHooks(value: boolean): WixDataInsertOptionsBuilder {
    return this.copy({ suppressHooks: value })
  }

  withShowDrafts(value: boolean): WixDataInsertOptionsBuilder {
    return this.copy({ showDrafts: value })
  }

  withIncludeReferences(value: boolean): WixDataInsertOptionsBuilder {
    return this.copy({ includeReferences: value })
  }

  withSaveReferences(value: boolean): WixDataInsertOptionsBuilder {
    return this.copy({ saveReferences: value })
  }

  build(): WixDataInsertOptions {
    return { ...this.options }
  }

  private copy(options: WixDataInsertOptions): WixDataInsertOptionsBuilder {
    return new WixDataInsertOptionsBuilderImpl({
      ...this.options,
      ...options,
    })
  }
}

/**
 * Creates a new insert options builder.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Create an insert options builder"
 * import { items, InsertOptionsBuilder } from '@wix/data'
 *
 * const options = InsertOptionsBuilder()
 *   .withSuppressHooks(true)
 *   .build()
 *
 * const item = await items.insert('myCollection', { foo: 'bar' }, options)
 * ```
 */
export const InsertOptionsBuilder: () => WixDataInsertOptionsBuilder = () =>
  new WixDataInsertOptionsBuilderImpl()
